import { describe, expect, it } from "vitest"
import { pySlice } from "@/components/viz/python/slice-ruler/py-slice"
import fixture from "../fixtures/py-slices.json"

/** Fixture generated by real CPython: s[a:b:c] for every combination of the values below. */
describe("pySlice matches CPython slicing", () => {
  const { s, cases } = fixture as {
    s: string
    cases: [number | null, number | null, number | null, string][]
  }

  it(`covers ${cases.length} start/stop/step combinations`, () => {
    const wrong = cases.filter(([a, b, c, want]) => pySlice(s, a, b, c) !== want)
    expect(wrong).toEqual([])
  })

  it("rejects step 0 like Python", () => {
    expect(() => pySlice(s, null, null, 0)).toThrow(/zero/)
  })
})
